CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('client','vendor','admin') NOT NULL DEFAULT 'client',avatar VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS venues (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_id INT UNSIGNED NULL,name VARCHAR(160) NOT NULL,description TEXT,type VARCHAR(40) NOT NULL,max_capacity INT UNSIGNED NOT NULL,square_footage INT UNSIGNED,base_rate DECIMAL(12,2) NOT NULL,peak_rate DECIMAL(12,2),security_deposit DECIMAL(12,2) DEFAULT 0,amenities JSON,catering_tier VARCHAR(100),address VARCHAR(255),city VARCHAR(100),rating DECIMAL(2,1) DEFAULT 0,review_count INT DEFAULT 0,status ENUM('active','maintenance','inactive') NOT NULL DEFAULT 'active',cover_image VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_id VARCHAR(20) UNIQUE NOT NULL,client_id INT UNSIGNED NOT NULL,venue_id INT UNSIGNED NOT NULL,event_title VARCHAR(180) NOT NULL,event_type VARCHAR(80),event_date DATE NOT NULL,start_time TIME,end_time TIME,guest_count INT UNSIGNED NOT NULL,time_slot VARCHAR(30),status ENUM('pending','approved','confirmed','completed','cancelled') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL UNIQUE,subtotal DECIMAL(12,2) NOT NULL,tax_rate DECIMAL(5,2) DEFAULT 18,tax_amount DECIMAL(12,2) DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL,deposit_amount DECIMAL(12,2) DEFAULT 0,deposit_paid DECIMAL(12,2) DEFAULT 0,payment_status ENUM('pending','partial','paid','refunded') DEFAULT 'pending',payment_method VARCHAR(50),paid_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,venue_id INT UNSIGNED NOT NULL,blocked_date DATE NOT NULL,block_type ENUM('booked','maintenance','blackout') NOT NULL DEFAULT 'blackout',booking_id INT UNSIGNED NULL,UNIQUE KEY venue_date (venue_id,blocked_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS booking_addons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,addon_name VARCHAR(160) NOT NULL,addon_type VARCHAR(40) NOT NULL,price_per_unit DECIMAL(12,2) NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,total_price DECIMAL(12,2) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id INT UNSIGNED NOT NULL,receiver_id INT UNSIGNED NOT NULL,booking_id INT UNSIGNED NULL,message TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,client_id INT UNSIGNED NOT NULL,venue_id INT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY booking_review (booking_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS enquiries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,status ENUM('new','in_progress','resolved') NOT NULL DEFAULT 'new',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX token_lookup (token_hash)) ENGINE=InnoDB;
INSERT INTO venues (name,description,type,max_capacity,square_footage,base_rate,peak_rate,security_deposit,amenities,catering_tier,address,city,rating,review_count,status,cover_image) SELECT 'The Grand Imperial Ballroom','A dramatic ballroom framed by crystal chandeliers, polished marble, and the quiet grandeur of a truly memorable evening.','Ballroom',500,12000,185000,240000,50000,'["Valet parking","AV suite","Bridal room"]','Signature culinary collection','MG Road','Mumbai',4.9,82,'active','https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1200&q=85' WHERE NOT EXISTS (SELECT 1 FROM venues WHERE name='The Grand Imperial Ballroom');
INSERT INTO venues (name,description,type,max_capacity,square_footage,base_rate,peak_rate,security_deposit,amenities,catering_tier,address,city,rating,review_count,status,cover_image) SELECT 'The Glasshouse Estate','An intimate estate where gardens, soft light, and architectural clarity create an unforgettable setting for celebrations.','Estate',220,8500,125000,160000,35000,'["Garden access","Valet parking","In-house florals"]','Garden-to-table menu','Alibaug Road','Alibaug',4.8,56,'active','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85' WHERE NOT EXISTS (SELECT 1 FROM venues WHERE name='The Glasshouse Estate');
INSERT INTO venues (name,description,type,max_capacity,square_footage,base_rate,peak_rate,security_deposit,amenities,catering_tier,address,city,rating,review_count,status,cover_image) SELECT 'Serein Garden Pavilion','A serene open-air pavilion surrounded by mature trees and a softly lit garden, made for graceful daytime gatherings.','Garden',180,6000,95000,130000,25000,'["Open air","Sound system","Cottage suite"]','Seasonal banquet menu','Lonavala Hills','Lonavala',4.7,41,'active','https://images.unsplash.com/photo-1478146896981-b80fe463b330?auto=format&fit=crop&w=1200&q=85' WHERE NOT EXISTS (SELECT 1 FROM venues WHERE name='Serein Garden Pavilion');
